(* [comment removed for export] *)
Definition egacc (eg : PMES.eghost) (evs : list PMW.evk) (al : Z) : Prop :=
  PMES.g_es eg = PMW.es_run (PMES.g_es eg0) evs /\ exists pay, 0 <= pay <= al /\ PMES.g_len eg = PMES.g_len eg0 + PMW.ind_run (PMES.g_es eg0) evs + pay.
(* [comment removed for export] *)
Definition wfin (eg : PMES.eghost) (code : Z) : Prop := code = snd (PMR.READ (PML.srep_chars rep)) /\ egacc eg (fst (fst (PMR.READ (PML.srep_chars rep)))) (snd (fst (PMR.READ (PML.srep_chars rep)))).
Hypothesis CONT : forall (fx' : FPState) (R' : bvmap 5 word) (M' : mem) (model' : Model) (cr' : credit) (ps' : PML.pstate) (code gp' rdst' : Z) (g' : PML.ls_state) (eg' : PMES.eghost),
  PML.fp_ok fx' ->
  PML.source_at M' Rr ch -> PML.parser_at M' (Rr + 320) ps' -> PML.isrc_at M' IS rep gp' rdst' -> PML.ec_at M' E code -> PML.ls_ok g' M' -> (g' = g0 \/ (g' = PML.LS2 /\ code <> 0)) ->
  PMES.enc_inv M' V S2 eg' -> PML.lits_ok M' ->
  PML.pcredit_x L cr' ps' (kx + PMX.kenc L eg') bx -> PML.wf_ps ps' ->
  wfin eg' code ->
  regs_preserved R0 R' -> L5C.hpres L LBk sp SS (RIXW.Wr Rr IS V E S2) M0 M' -> model_but_vm model0 model' -> hi_heap HI (PML.ps_blocks ps' ++ LBo ++ PMES.g_lbv eg') cr' M' (m_vmmaps model') ->
  srealizes RSEGS SCFG (@PML.cfg fx' R' r M' model') K.

(* [comment removed for export] *)
Definition ginv := RIXW.ginv L HI STRTOD_SCR WD_SCR LBo sp Rr IS V E S2 ch kx bx rep g0 M0 model0.
Lemma lay : 2 ^ 40 <= sp /\ sp mod 16 = 0 /\ sp <= Rr /\ Rr + 592 <= hl_sptop L /\ sp <= IS /\ IS + 272 <= hl_sptop L /\ sp <= V /\ V + 8 <= hl_sptop L /\ sp <= E /\ E + 16 <= hl_sptop L /\
            0xfb000 <= hl_ceil L /\ hl_ceil L + SS <= sp /\ SS = 176 + PMX.PSOMEX_SCR STRTOD_SCR WD_SCR /\ 9376 <= PMX.PSOMEX_SCR STRTOD_SCR WD_SCR /\
            PMX.PSOMEX_SCR STRTOD_SCR WD_SCR = 112 + PMX.PFX_SCR STRTOD_SCR WD_SCR.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00!@'0/L;/STRTOD_SCR;/WD_SCR;/sp;/Rr;/IS;/V;/E;/rep;/SPOK;/Hceil;/Htop;/OR;/OI;/OV;/OE;").
Qed.
Lemma layx : sp <= S2 /\ S2 + 24 <= hl_sptop L /\ V + PMES.ENC_SIZE <= hl_sptop L /\ PMS.PF_SCR STRTOD_SCR + 1024 <= PMX.PFX_SCR STRTOD_SCR WD_SCR /\ 9264 <= PMS.PF_SCR STRTOD_SCR /\ PMES.ENC_SIZE = 408.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00!;'1/L;/STRTOD_SCR;/WD_SCR;/sp;/P;/P;/V;/S2;/rep;/OVX;/OS2;").
Qed.
