Definition rsof := RKW.rsof IS rep.
(* [comment removed for export] *)
Definition wst (M : mem) (ps : PML.pstate) (c : PMR.ctrl) (w : list Z) : Prop := PMR.rm_match c M P ps /\ PMW.win_bytes M ps w.
(* [comment removed for export] *)
Definition rinvA (M : mem) (ps : PML.pstate) (gp rdst : Z) (bof : bool) (eg : PMES.eghost) : Prop :=
  exists c w evs al F', wst M ps c w /\ egacc eg evs al /\ RKW.accA rep evs al F' (rsof c w gp bof rdst).
(* [comment removed for export] *)
Definition rinvP (M : mem) (ps : PML.pstate) (gp rdst : Z) (bof : bool) (eg : PMES.eghost) : Prop :=
  exists c w evs al F' w0 gp0 bof0 rdst0, wst M ps c w /\ egacc eg evs al /\ RKW.accA rep evs al F' (rsof c w0 gp0 bof0 rdst0) /\ PMR.refill (rsof c w0 gp0 bof0 rdst0) = (rsof c w gp bof rdst, 0).
(* [comment removed for export] *)
Definition rinvB0 (M : mem) (ps : PML.pstate) (gp rdst : Z) (bof : bool) (eg : PMES.eghost) : Prop :=
  exists tA c w, PMR.rloop (PMR.rfuel (PML.srep_chars rep)) (PMRR.rs0 (PML.srep_chars rep)) = tA /\ PMRR.t_code tA = 0 /\ egacc eg (PMRR.t_evs tA) (PMRR.t_al tA) /\ wst M ps c w /\ PMRR.t_rs tA = rsof c w gp bof rdst.
(* [comment removed for export] *)
Definition rinvB (M : mem) (ps : PML.pstate) (gp rdst : Z) (bof : bool) (eg : PMES.eghost) : Prop :=
  exists tA c w F', PMR.rloop (PMR.rfuel (PML.srep_chars rep)) (PMRR.rs0 (PML.srep_chars rep)) = tA /\ PMRR.t_code tA = 0 /\ egacc eg (PMRR.t_evs tA) (PMRR.t_al tA) /\ wst M ps c w /\
    PMR.rtail (PMR.rfuel (PML.srep_chars rep)) (PMR.sw (PMRR.t_rs tA)) = PMR.rtail F' (rsof c w gp bof rdst) /\ PMRR.nchunks (rsof c w gp bof rdst) + 1 <= Z.of_nat F'.
(* [comment removed for export] *)
Definition rinvE (eg : PMES.eghost) : Prop := exists tA, PMR.rloop (PMR.rfuel (PML.srep_chars rep)) (PMRR.rs0 (PML.srep_chars rep)) = tA /\ egacc eg (PMRR.t_evs tA) (PMRR.t_al tA) /\ PMRR.t_code tA = PMR.E_EOF.
(* [comment removed for export] *)
Definition rinvX (M : mem) (ps : PML.pstate) (gp rdst : Z) (bof : bool) (eg : PMES.eghost) (code : Z) : Prop :=
  exists tA, PMR.rloop (PMR.rfuel (PML.srep_chars rep)) (PMRR.rs0 (PML.srep_chars rep)) = tA /\ egacc eg (PMRR.t_evs tA) (PMRR.t_al tA) /\
   ((PMRR.t_code tA <> 0 /\ code = PMRR.t_code tA) \/
    (PMRR.t_code tA = 0 /\ exists tB, PMR.rtail (PMR.rfuel (PML.srep_chars rep)) (PMR.sw (PMRR.t_rs tA)) = tB /\
       ((snd tB <> 0 /\ code = snd tB) \/ (snd tB = 0 /\ code = 0 /\ exists c w, wst M ps c w /\ fst tB = rsof c w gp bof rdst)))).
(* [comment removed for export] *)
Definition accC0 (tA : PMRR.rres) (rsB : PMR.rstate) (eg : PMES.eghost) : Prop :=
  PMR.rloop (PMR.rfuel (PML.srep_chars rep)) (PMRR.rs0 (PML.srep_chars rep)) = tA /\ PMRR.t_code tA = 0 /\ egacc eg (PMRR.t_evs tA) (PMRR.t_al tA) /\ PMR.rtail (PMR.rfuel (PML.srep_chars rep)) (PMR.sw (PMRR.t_rs tA)) = (rsB, 0).
Definition rinvC0 (M : mem) (ps : PML.pstate) (gp rdst : Z) (bof : bool) (eg : PMES.eghost) : Prop := ltac2:(Rpl.RP.run_i (rplG ()) 6 "S20|30;!1+=+6$M;R%~R!1+2!1,3|600;!1+4!1+2!1,30$ps;R+5$gp;R+6$rdst;R+6$bof;R+7$eg;R+8!2+9':$tA;R':!2+9+;$rsB;R+;!2+9+<$c;R+<!2+91$w;R1!2+>!3'?#4#3#5!2+>!4'@#:#9#2#1!3+A+;#3!5'B#2#1#8#6#7").
Definition rinvC (M : mem) (ps : PML.pstate) (gp rdst : Z) (bof : bool) (eg : PMES.eghost) : Prop := ltac2:(Rpl.RP.run_i (rplG ()) 6 "S30|30;!1+=+6!5'B#3#2#9#7#8$M;R%~R!1+2!1,3|600;!1+4!1+2!1,30$ps;R+5$gp;R+6$rdst;R+6$bof;R+7$eg;R+8!2+9':$tA;R':!2+9+;$rsB;R+;!2+9+<$c;R+<!2+91$w;R1!2+9+C$F';R+C!2+>!3'?#5#4#6!2+>!3+A+7!1'D#4,E!2+>!4'@#;#:#3#2!2+>!3+A+6!2'F!1'G!1'H/rep;#4!2'F#12!2'I!2'J!2'J!1'K2!1'L2!1,M,N!1'O#1").
(* [comment removed for export] *)
Definition rinvPC (M : mem) (ps : PML.pstate) (gp rdst : Z) (bof : bool) (eg : PMES.eghost) : Prop :=
  exists tA rsB c w F'' rs, accC0 tA rsB eg /\ PMR.r_eof rsB = false /\ wst M ps c w /\ w <> [] /\
    PMR.refill rs = (rsof c w gp bof rdst, 0) /\ PMR.rcheck (PMR.rfuel (PML.srep_chars rep)) rsB = PMR.rcheck (S F'') rs /\ PMRR.nchunks (rsof c w gp bof rdst) + 1 <= Z.of_nat F''.
(* [comment removed for export] *)
Definition rinvC00 (M : mem) (ps : PML.pstate) (gp rdst : Z) (bof : bool) (eg : PMES.eghost) : Prop :=
  exists tA rsB c F'', accC0 tA rsB eg /\ PMR.r_eof rsB = false /\ wst M ps c [] /\
    (rdst = 2 -> PMR.rcheck (PMR.rfuel (PML.srep_chars rep)) rsB = 0) /\
    (rdst = 0 -> PMR.rcheck (PMR.rfuel (PML.srep_chars rep)) rsB = PMR.rcheck F'' (rsof c [] gp bof rdst) /\ PMRR.nchunks (rsof c [] gp bof rdst) + 1 <= Z.of_nat F'').

