Lemma ginv_stack : forall M M' model cr ps gp rdst code bof g B eg lo hi,
  ginv M model cr ps gp rdst code bof g B eg -> TK.samem (fun a => ~ (lo <= a < hi)) M M' -> mem_grows M M' -> sp - SS <= lo -> hi <= sp ->
  ginv M' model cr ps gp rdst code bof g B eg.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S20|30;%~R!1+2!1,3|600;!1+4!1+2!1,30$M;R1$M';R1$model;R+R$cr;R'S$ps;R+5$gp;R+6$rdst;R+6$code;R+6$bof;R+7$g;R+T$B;R+6$eg;R+8$lo;R+6$hi;R+6$~R!;'V#>#<#;#:#9#8#7#6#5#4#3$~R!3'`0$a;R+6!1'^8!2+>!2'I#4#1!2'^H#1#3#?#>$~R!2'`1#@#?$~R!2'I!2'^B/sp;/SS;#5$~R!2'I#5/sp;!^<'`2/SCFG_P;/L;/HI;/STRTOD_SCR;/WD_SCR;/HIok;/LAY;/LBo;/sp;/r;/Rr;/IS;/V;/E;/S2;/ch;/kx;/bx;/rep;/g0;/R0;/M0;/model0;/K;/Hn;/SPOK;/Hceil;/Htop;/OR;/OI;/OV;/OE;/OVX;/OS2;/INrep;/NEch;'^N/CONT;#C#B#A#@#?#>#=#<#;#:#9#8#7#6#5#4#3#2#1").
Qed.
Lemma ginv_ptrans : forall M M' model model' cr cr' ps ps' gp rdst bof code' g' B eg spc scr eg',
  ginv M model cr ps gp rdst 0 bof g0 B eg ->
  L5C.hpres L LBo spc scr (PMX.W_parx P V E S2) M M' -> sp - SS <= spc - scr -> spc <= sp -> 0 <= scr -> spc mod 16 = 0 ->
  model_but_vm model model' -> hi_heap HI (PML.ps_blocks ps' ++ LBo ++ PMES.g_lbv eg') cr' M' (m_vmmaps model') ->
  PML.parser_at M' P ps' -> PML.wf_ps ps' -> (code' = 0 -> PML.ws_ok ps') -> PML.win_ok M' (LBo ++ PMES.g_lbv eg') ps' -> PML.buf_bound ps' B -> PML.ec_at M' E code' -> PML.ls_ok g' M' ->
