(* [comment removed for export] *)
Lemma gcells : forall M model cr ps gp rdst code bof g B eg, ginv M model cr ps gp rdst code bof g B eg ->
  PML.u64 M (Rr + 240) IS /\ PML.u64 M IS PML.VT_ISS /\ PML.u32 M (IS + 152) rdst /\ PML.u8 M (IS + 152) rdst /\ (rdst = 0 \/ rdst = 2) /\ PML.img_ro M /\
  PML.u64 M (Rr + 288) 0 /\ PML.u64 M (Rr + 312) V /\ PML.u64 M (Rr + 512) (RB.we ps) /\ PML.u64 M (Rr + 520) (RB.wp ps) /\ 0 <= RB.wp ps <= RB.we ps /\ RB.we ps < 2 ^ 62 /\
