(* [comment removed for export] *)
Lemma pcd_call : forall m, atC m -> forall (fx : FPState) R M model cr ps gp rdst bof B eg,
  (2 * (D + n - gp) + ee rdst) * 2 < m ->
  PML.fp_ok fx -> ginv M model cr ps gp rdst 0 bof g0 B eg -> rinvPC M ps gp rdst bof eg -> cd_regs R -> RS.cd_frame M sp r R0 ->
