(* [comment removed for export] *)
Definition muB (gp rdst : Z) : Z := 2 * (D + n - gp) + ee rdst.
Definition atB (m : Z) : Prop := forall (fx : FPState) R M model cr ps gp rdst bof B eg,
  muB gp rdst < m -> PML.fp_ok fx -> ginv M model cr ps gp rdst 0 bof g0 B eg -> rinvB M ps gp rdst bof eg ->
  (PML.ps_more ps = true -> rdst = 2) (* [comment removed for export] *) ->
  rn_regs R -> rn_fr M -> srealizes RSEGS SCFG (@PML.cfg fx R RT.LOOPB M model) K.

