Definition atA (m : Z) : Prop := forall (fx : FPState) R M model cr ps gp rdst bof B eg,
  muA ps gp rdst < m -> PML.fp_ok fx -> ginv M model cr ps gp rdst 0 bof g0 B eg -> rinvA M ps gp rdst bof eg -> PML.ps_more ps = true (* [comment removed for export] *) ->
  PML.win_ok M LBo ps -> PMX.enc_sync ps eg (* [comment removed for export] *) ->
  rn_regs R -> getr R 20%bv = Z_to_bv 64 1 -> getr R 21%bv = Z_to_bv 64 2 -> rn_fr M ->
  srealizes RSEGS SCFG (@PML.cfg fx R RT.LOOPA M model) K.

(* [comment removed for export] *)
Lemma psome_call : forall m, atA m -> forall (fx : FPState) R M model cr ps gp rdst bof B eg,
  muA ps gp rdst <= m -> PML.fp_ok fx -> ginv M model cr ps gp rdst 0 bof g0 B eg -> rinvP M ps gp rdst bof eg -> PML.ps_more ps = true -> PML.win_ok M LBo ps -> PMX.enc_sync ps eg ->
  (PMS.win_exhausted ps -> rdst = 2) (* [comment removed for export] *) -> rn_regs R -> rn_fr M ->
  getr R 1%bv = Z_to_bv 64 RT.RN_R_PSOME -> getr R 10%bv = Z_to_bv 64 (Rr + 320) -> getr R 11%bv = Z_to_bv 64 V -> getr R 12%bv = Z_to_bv 64 E ->
  getr R 19%bv = Z_to_bv 64 (RB.wp ps) -> getr R 22%bv = Z_to_bv 64 (RB.we ps) -> getr R 20%bv = Z_to_bv 64 1 -> getr R 21%bv = Z_to_bv 64 2 ->
