Lemma rn_entry : forall (fx : FPState) M model cr gp sb bptr eg,
  PML.fp_ok fx -> ginv M model cr (PMS.ps_init sb bptr) gp 0 0 true g0 0 eg -> PMX.enc_sync (PMS.ps_init sb bptr) eg -> egacc eg [] 0 -> gp = D -> rd_frame M ->
